# Immagini degli step (card grafiche), incorporate nel file
IMAGES = {"step1.png": "", "step2.png": "", "step3.png": ""}


def image_files():
    return [discord.File(io.BytesIO(base64.b64decode(b)), filename=n) for n, b in IMAGES.items()]


def clean(s: str) -> str:
    """Confronta anche nomi con font speciali (𝐕𝐨𝐮𝐜𝐡𝐞𝐬 -> vouches)."""
    return unicodedata.normalize("NFKC", s).lower()


