bot = commands.Bot(command_prefix="!", intents=discord.Intents.default())


class VouchGuide(ui.LayoutView):
    """Un solo messaggio: scelta lingua ➜ guida completa nello stesso pannello."""

    def __init__(self, guild, seller, product, buyer, vouch_text, channel):
        super().__init__(timeout=3600)
        self.guild, self.seller, self.product, self.buyer = guild, seller, product, buyer
        self.vouch_text, self.channel = vouch_text, channel
        self.lang = None
        self.copy_msg = None
        self.created = int(time.time())
        self.refresh()

    def refresh(self):
        self.clear_items()
        self.add_item(self.build())

    # ---------------- componenti ----------------
    def header(self, text):
        icon = self.guild.icon.url if self.guild.icon else None
        if icon:
            return ui.Section(ui.TextDisplay(text), accessory=ui.Thumbnail(icon))
        return ui.TextDisplay(text)

    def lang_row(self):
        select = ui.Select(
            placeholder="🌍  Select your language / Seleziona la lingua",
            options=[discord.SelectOption(label=v["name"], value=k, emoji=v["flag"], default=(k == self.lang))
                     for k, v in T.items()],
        )

        async def on_select(interaction: discord.Interaction):
            first_time = self.lang is None
            self.lang = select.values[0]
            self.refresh()
            if first_time:
                await interaction.response.edit_message(view=self, attachments=image_files())
            else:
                await interaction.response.edit_message(view=self)

        select.callback = on_select
        return ui.ActionRow(select)

    def build(self):
        # ---------- schermata iniziale: lingua ----------
        if self.lang is None:
            who = f"{self.buyer.mention}\n" if self.buyer else ""
            return ui.Container(
                self.header(f"{who}## {self.guild.name}\n-# Vouch Guide  •  **{self.product}**\n\n"
                            "🌍 **Choose your language to continue**\n-# Seleziona la tua lingua per continuare"),
                ui.Separator(spacing=discord.SeparatorSpacing.large),
                self.lang_row(),
                accent_colour=COLOR,
            )

        # ---------- guida ----------
        t = T[self.lang]

        copy_btn = ui.Button(label=t["copy"], emoji="📋", style=discord.ButtonStyle.primary)
        copy_btn.callback = self.on_copy

        if self.channel:
            step2_right = ui.Button(label=t["go"], emoji="↗️", url=self.channel.jump_url)
        else:
            step2_right = ui.Button(label=t["go"], emoji="↗️", style=discord.ButtonStyle.secondary, disabled=True)

        return ui.Container(
            self.header(
                f"## {t['title']}\n-# {t['sub']}\n\n"
                f"**{t['product']}** ┃ `{self.product}`\n**{t['seller']}** ┃ {self.seller.mention}"
            ),
            ui.Separator(spacing=discord.SeparatorSpacing.large),

            # STEP 1
            ui.Section(
                ui.TextDisplay(f"-# {t['step']} 1 / 3\n### {t['s1']}\n> {self.vouch_text}"),
                accessory=copy_btn,
            ),
            ui.TextDisplay(f"-# {t['s1d']}"),
            ui.MediaGallery(discord.MediaGalleryItem("attachment://step1.png")),
            ui.Separator(spacing=discord.SeparatorSpacing.large),

            # STEP 2
            ui.Section(
                ui.TextDisplay(f"-# {t['step']} 2 / 3\n### {t['s2']}\n-# {t['s2d']}"),
                accessory=step2_right,
            ),
            ui.MediaGallery(discord.MediaGalleryItem("attachment://step2.png")),
            ui.Separator(spacing=discord.SeparatorSpacing.large),

            # STEP 3
            ui.TextDisplay(f"-# {t['step']} 3 / 3\n### {t['s3']}\n-# {t['s3d']}"),
            ui.MediaGallery(discord.MediaGalleryItem("attachment://step3.png")),
            ui.Separator(spacing=discord.SeparatorSpacing.large),

            self.lang_row(),
            ui.TextDisplay(f"-# {t['thanks']}  •  {self.guild.name}  •  <t:{self.created}:f>"),
            accent_colour=COLOR,
        )

    # ---------------- bottone Copy ----------------
    async def on_copy(self, interaction: discord.Interaction):
        # Messaggio PUBBLICO con solo il testo del vouch -> "Copy Text" funziona ovunque
        if self.copy_msg:
            try:
                await self.copy_msg.delete()
            except discord.HTTPException:
                pass
        await interaction.response.send_message(
            self.vouch_text,
            allowed_mentions=discord.AllowedMentions.none(),
            delete_after=COPY_DELETE_AFTER or None,
        )
        self.copy_msg = await interaction.original_response()

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if self.buyer and interaction.user.id not in (self.buyer.id, self.seller.id):
            await interaction.response.send_message("❌ This panel is not for you.", ephemeral=True)
            return False
        return True


def build_panel(guild, seller, product_label, buyer):
    """Crea il testo del vouch e il pannello per il prodotto (o lista prodotti) indicato."""
    role = guild.get_role(FOUNDER_ROLE_ID)
    tag = f"{role.mention} | {seller.mention}" if role else f"| {seller.mention}"
    vouch_text = f"Vouch {tag} took payment | Product: {product_label}"

    channel = guild.get_channel(VOUCH_CHANNEL_ID) if VOUCH_CHANNEL_ID else None
    if channel is None:
        channel = discord.utils.find(lambda c: VOUCH_CHANNEL_KEYWORD in clean(c.name), guild.text_channels)

    return VouchGuide(guild, seller, product_label, buyer, vouch_text, channel)


PANEL_MENTIONS = discord.AllowedMentions(users=True, roles=False, everyone=False)


class MultiPicker(ui.View):
    """Menu privato (solo tu lo vedi) per scegliere 2 o più script."""

    def __init__(self, seller, buyer):
        super().__init__(timeout=300)
        self.seller, self.buyer = seller, buyer

        select = ui.Select(
            placeholder="🧩  Select the scripts purchased (2+)",
            min_values=2,
            max_values=len(PRODUCTS),
            options=[discord.SelectOption(label=p, value=p, emoji="📦") for p in PRODUCTS],
        )
        select.callback = self.on_pick
        self.select = select
        self.add_item(select)

    async def on_pick(self, interaction: discord.Interaction):
        # Mantiene l'ordine della lista PRODUCTS
        chosen = [p for p in PRODUCTS if p in self.select.values]
        # Se ha scelto tutti gli script -> diventa automaticamente "All Script"
        label = ALL_LABEL if len(chosen) == len(PRODUCTS) else ", ".join(chosen)

        await interaction.response.edit_message(content=f"✅ Panel sent • **{label}**", view=None)
        await interaction.followup.send(
            view=build_panel(interaction.guild, self.seller, label, self.buyer),
            allowed_mentions=PANEL_MENTIONS,
        )
        self.stop()

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return interaction.user.id == self.seller.id


PRODUCT_CHOICES = (
    [app_commands.Choice(name=p, value=p) for p in PRODUCTS]
    + [
        app_commands.Choice(name="🧩 Multi Scripts (choose 2+)", value=MODE_MULTI),
        app_commands.Choice(name="⭐ All Scripts", value=MODE_ALL),
    ]
)


@bot.tree.command(name="tutorialvouch", description="Send the vouch guide to a buyer")
@app_commands.describe(product="Product purchased (or Multi / All Scripts)",
                       buyer="(Optional) Only this buyer can use the panel")
@app_commands.choices(product=PRODUCT_CHOICES)
@app_commands.default_permissions(administrator=True)
@app_commands.guild_only()
async def tutorialvouch(interaction: discord.Interaction, product: app_commands.Choice[str],
                        buyer: discord.Member | None = None):
    guild = interaction.guild

    # ---- MULTI: apre un menu privato per scegliere gli script ----
    if product.value == MODE_MULTI:
        await interaction.response.send_message(
            "🧩 **Multi Scripts** — select all the scripts the buyer purchased:",
            view=MultiPicker(interaction.user, buyer),
            ephemeral=True,
        )
        return

    # ---- ALL SCRIPTS / singolo script ----
    label = ALL_LABEL if product.value == MODE_ALL else product.value
    await interaction.response.send_message(
        view=build_panel(guild, interaction.user, label, buyer),
        allowed_mentions=PANEL_MENTIONS,
    )


@bot.event
async def on_ready():
    try:
        if GUILD_ID:
            g = discord.Object(id=GUILD_ID)
            bot.tree.copy_global_to(guild=g)
            synced = await bot.tree.sync(guild=g)
        else:
            synced = await bot.tree.sync()
        print(f"✅ Synced {len(synced)} command(s)")
    except Exception as e:
        print(f"❌ Sync error: {e}")
    print(f"✅ Logged in as {bot.user} ({bot.user.id})")


if not TOKEN:
    raise SystemExit("❌ DISCORD_TOKEN mancante: aggiungilo nelle Variables di Railway.")

try:
    bot.run(TOKEN)
except discord.LoginFailure:
    raise SystemExit("❌ Token non valido: fai Reset Token nel Developer Portal e aggiorna DISCORD_TOKEN su Railway.")
